'use strict';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
let me=null, meta={},data={},currentProject=null,currentTab='resumen',settings=null;
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escape, statusNames={pendiente:'Pendiente de aportar',recibido:'Recibido',en_revision:'En revisión',validado:'Validado',rechazado:'Rechazado',caducado:'Caducado',no_aplicable:'No aplicable',pendiente_revision:'Aplicabilidad por resolver',aplica:'Aplicable',completada:'Completada',en_curso:'En curso',esperando_tercero:'Esperando a tercero',cancelada:'Cancelada',parcial:'Parcial'};
statusNames.sustituido='Sustituido en origen';statusNames.revocado='Publicación revocada';
const label=s=>statusNames[s]||s;
const dt=s=>s?new Date(s.length===10?s+'T12:00:00':s).toLocaleDateString('es-ES',{timeZone:'Europe/Madrid',day:'2-digit',month:'short',year:'numeric'}):'Sin fecha definida';
const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Madrid'});
const nameP=id=>data.projects?.find(p=>p.id===id)?.name||'Obra';
const nameC=id=>data.companies?.find(c=>c.id===id)?.name||'Ámbito de obra';
const tag=(text,color='gris')=>`<span class="badge ${E(color)}"><i class="dot"></i>${E(text)}</span>`;
const docTag=s=>tag(label(s),s==='validado'?'verde':s==='rechazado'||s==='caducado'?'rojo':s==='no_aplicable'?'gris':'ambar');
const healthTag=h=>tag({verde:'Completa',ambar:'Pendientes',rojo:'Bloqueada',gris:'Por definir'}[h.color],h.color);
const btn=(text,action,id='',cls='')=>`<button class="${cls}" data-action="${action}" data-id="${E(id)}">${E(text)}</button>`;
const options=(items,selected='')=>items.map(x=>{let [value,text]=Array.isArray(x)?x:[x.id,x.name];return `<option value="${E(value)}" ${value===selected?'selected':''}>${E(text)}</option>`}).join('');
const input=(name,title,type='text',value='',required=false,cls='')=>`<label class="${cls}">${E(title)}<input name="${E(name)}" type="${type}" value="${E(value)}" ${required?'required':''}></label>`;
const select=(name,title,items,selected='',cls='')=>`<label class="${cls}">${E(title)}<select name="${name}">${options(items,selected)}</select></label>`;
const textarea=(name,title,value='',cls='full')=>`<label class="${cls}">${E(title)}<textarea name="${name}">${E(value)}</textarea></label>`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),5500)}
async function api(path,method='GET',body){let headers={};if(me?.csrf)headers['X-CSRF-Token']=me.csrf;if(body&&!(body instanceof FormData))headers['Content-Type']='application/json';let r=await fetch('/api'+path,{method,headers,body:body instanceof FormData?body:body?JSON.stringify(body):undefined});let out=await r.json().catch(()=>({detail:'Respuesta no válida'}));if(!r.ok){const error=new Error(typeof out.detail==='string'?out.detail:JSON.stringify(out.detail));error.status=r.status;throw error;}return out}
function can(pid,action,company=null,category=null){
 if(me?.admin)return true;
 return (meta.grants||[]).some(g=>{
  const ps=JSON.parse(g.permissions),cs=JSON.parse(g.categories);
  return g.project_id===pid&&g.role!=='firmante'&&ps.includes(action)&&(!g.company_id||g.company_id===company)&&(!category||cs.includes(category)||cs.includes('*'))&&(!['salud','laboral','economico','bancario'].includes(category)||cs.includes(category))&&(category!=='salud'||ps.includes('health'));
 });
}
function showModal(title,html,submit,submitLabel='Guardar'){ $('#modal-content').innerHTML=`<div class="modal-head"><h2>${E(title)}</h2>${btn('×','close')}</div><form id="modal-form"><div class="modal-body">${html}<p class="error" id="form-error" role="alert"></p>${submit?`<div class="modal-footer">${btn('Cancelar','close')}<button class="primary" type="submit">${E(submitLabel)}</button></div>`:''}</div></form>`;modal.showModal();if(submit)$('#modal-form').onsubmit=async ev=>{ev.preventDefault();let button=ev.submitter;button.disabled=true;try{await submit(Object.fromEntries(new FormData(ev.target)),ev.target)}catch(e){$('#form-error').textContent=e.message}finally{button.disabled=false}};$('#modal-form').querySelectorAll('button[data-action]').forEach(b=>b.type='button')}
function close(){modal.close()}
function pageTitle(title,description,action=''){return `<div class="page-title"><div><div class="eyebrow">ESPACIO DE TRABAJO · NM2022 S.L.</div><h1>${E(title)}</h1><p>${E(description)}</p></div>${action}</div>`}
function brandMarkup(cls=''){return `<div class="${cls}"><img src="/static/brand/nou-mallorca.svg" alt="Nou Mallorca" width="320" height="113" decoding="async"></div>`}
function shell(html){let route=location.hash.split('/')[0]||'#dashboard';const nav=[['dashboard','◫','Dashboard'],['pipeline','▥','Pipeline'],['obras','▦','Obras'],['empresas','◇','Empresas'],['trabajadores','♙','Trabajadores'],['equipos','⚙','Equipos'],['documentos','▤','Documentos y firmas'],['tareas','☑','Tareas'],['calendario','▣','Calendario'],['importar','↥','Importar desde chat'],['configuracion','≡','Configuración']];app.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">${brandMarkup('sidebar-brand')}<small>GESTIÓN DE OBRAS</small></div><div class="nav-label">PRINCIPAL</div><nav>${nav.filter(n=>!['configuracion','importar'].includes(n[0])||me.admin).map(([id,icon,text])=>`<a href="#${id}" class="${route==='#'+id||(route==='#obra'&&id==='obras')?'active':''}"><span class="nav-icon">${icon}</span>${text}</a>`).join('')}</nav><div class="sidebar-footer"><span class="avatar">${E(me.name.slice(0,2).toUpperCase())}</span>${E(me.name)}<br>${btn('Cerrar sesión','logout')}</div></aside><main class="main"><header class="topbar"><span class="breadcrumbs">Gestión / ${E(nav.find(n=>'#'+n[0]===route)?.[2]||'Expediente de obra')}</span><div class="top-right"><span class="today">${dt(today())}</span><span class="trial">FIRMA Y CORREO · PRUEBAS</span><span class="avatar">${E(me.name.slice(0,2).toUpperCase())}</span></div></header><div class="content">${html}<p class="legal">Habilitación documental: no certifica la seguridad ni sustituye la autorización operativa del responsable competente. Reglas preventivas sujetas a revisión.</p></div></main></div>`}
function loginPage(error=''){app.innerHTML=`<main class="auth">${brandMarkup('auth-brand')}<div class="eyebrow">NM2022 S.L. · ESPACIO PRIVADO</div><h1 class="sr-only">Nou Mallorca · acceso a gestión de obras</h1><p>Obras, documentación y próximos pasos, en un mismo lugar.</p><form id="login">${input('email','Correo electrónico','email','',true)}${input('password','Contraseña','password','',true)}<p class="error" id="login-error">${E(error)}</p><button class="primary">Entrar al espacio de trabajo →</button></form><div class="notice">Acceso por invitación. Firma y correo funcionan en modo de prueba.</div></main>`;$('#login').onsubmit=async ev=>{ev.preventDefault();try{let r=await api('/login','POST',Object.fromEntries(new FormData(ev.target)));me=r.user;await boot()}catch(e){$('#login-error').textContent=e.message}}}
async function boot(){try{meta=await api('/me');me=meta.user;data=await api('/dashboard');await route()}catch(e){if(e.status===401){me=null;if(location.hash.startsWith('#invitacion/'))await invitationPage(location.hash.split('/')[1]);else loginPage()}else{app.innerHTML=`<main class="auth">${brandMarkup('auth-brand')}<h1>No se ha podido cargar el espacio</h1><p class="error">${E(e.message)}</p>${btn('Reintentar','reload-app')}</main>`}}}
async function refresh(){data=await api('/dashboard');await route()}
async function route(){let [r,id]=location.hash.slice(1).split('/');if(r==='invitacion'){return invitationPage(id)}if(!me)return loginPage();if(r==='firma')return signaturePage(id);if(r==='obra'){currentProject=await api('/projects/'+id);return renderProject()}currentProject=null;switch(r){case 'pipeline':return renderPipeline();case 'obras':return renderWorks();case 'empresas':return renderEntities('companies');case 'trabajadores':return renderEntities('workers');case 'equipos':return renderEntities('equipment');case 'documentos':return renderDocs();case 'tareas':return renderTasks();case 'calendario':return renderCalendar();case 'importar':return renderChatImport();case 'configuracion':settings=await api('/settings');return renderSettings();default:return renderDashboard()}}
function taskRows(ts,limit=8){if(!ts.length)return '<div class="empty">No hay actuaciones en esta vista.</div>';return ts.slice(0,limit).map(t=>`<div class="task-row"><span class="priority ${E(t.priority)}"></span><div class="body"><p>${E(t.title)}</p><small>${E(nameP(t.project_id))} · ${E(t.owner||'Seguimiento sin responsable')} · ${dt(t.due)}</small></div><a href="#obra/${E(t.project_id)}">Ver →</a></div>`).join('')}
function projectTable(ps){return `<div class="panel table-scroll"><table><thead><tr><th>Obra / municipio</th><th>Fase</th><th>Habilitación documental</th><th>Próximo paso</th><th>Responsable / fecha</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><a href="#obra/${p.id}"><strong>${E(p.name)}</strong></a><small>${E(p.code)} · ${E(p.municipality||'Municipio sin definir')}</small>${p.paused?tag('Paralizada','rojo'):''}</td><td>${E(meta.phases[p.phase])}<small>${dt(p.details.start)} — ${dt(p.details.end)}</small></td><td>${healthTag(p.health)}<small>${p.health.critical} bloqueos · ${p.health.complete}/${p.health.total} resueltos</small></td><td>${E(p.next_action?.title||'Sin siguiente actuación definida')}</td><td>${E(p.next_action?.owner||'Sin asignar')}<small>${dt(p.next_action?.due)}</small></td><td><a href="#obra/${p.id}" aria-label="Abrir ${E(p.name)}">↗</a></td></tr>`).join('')||'<tr><td colspan="6">No hay obras que coincidan.</td></tr>'}</tbody></table></div>`}
function renderDashboard(){let pending=data.tasks.filter(t=>!['completada','cancelada'].includes(t.status)),review=data.documents.filter(d=>d.versions?.[0]&&['recibido','en_revision'].includes(d.versions[0].effective_status)),sign=data.signatures.filter(s=>['pendiente','parcial'].includes(s.status)),blocked=data.projects.filter(p=>p.health.color==='rojo');shell(pageTitle('Todo bajo control','La visión general de tus obras y lo que necesita atención.',me.admin?btn('+ Nueva obra','new-project','','primary'):'')+`<div class="stats"><button class="stat good" data-action="go" data-id="obras"><div class="label">Obras en seguimiento <span>↗</span></div><div class="number">${data.projects.length}</div><div class="hint">${data.projects.filter(p=>p.phase===3).length} en ejecución</div></button><button class="stat critical" data-action="filter-blocked"><div class="label">Obras con bloqueos <span>!</span></div><div class="number">${blocked.length}</div><div class="hint">${data.projects.filter(p=>p.health.color==='gris').length} con aplicabilidad por resolver</div></button><button class="stat warn" data-action="go" data-id="documentos"><div class="label">Documentos por revisar <span>▤</span></div><div class="number">${review.length}</div><div class="hint">Recibidos y en revisión</div></button><button class="stat" data-action="go" data-id="documentos"><div class="label">Firmas pendientes <span>↗</span></div><div class="number">${sign.length}</div><div class="hint">Adaptador de prueba activo</div></button></div><div class="section-head"><h2>Tus obras</h2><a href="#pipeline">Ver pipeline →</a></div>${projectTable(data.projects)}<div class="twocol"><section><div class="section-head"><h2>Próximas actuaciones</h2><a href="#tareas">Ver todas →</a></div><div class="panel">${taskRows(pending,5)}</div></section><section><div class="section-head"><h2>Atención documental</h2><small>Acciones concretas</small></div><div class="panel">${data.projects.filter(p=>p.health.color!=='verde').slice(0,4).map(p=>`<div class="task-row"><div class="body"><p>${E(p.name)}</p><small>${E(p.health.causes[0]||'Completar los datos de la obra y resolver aplicabilidad.')}</small></div>${healthTag(p.health)}</div>`).join('')||'<div class="empty">No hay avisos documentales.</div>'}</div><div class="notice">Subir un archivo no lo valida. Firmarlo no implica aprobación técnica.</div></section></div>`)}
function renderWorks(){shell(pageTitle('Obras','Todos los expedientes, fases y siguientes pasos.',me.admin?btn('+ Nueva obra','new-project','','primary'):'')+`<div class="toolbar"><input id="work-search" placeholder="Buscar obra, municipio o código…" aria-label="Buscar obras"><select id="work-filter" aria-label="Estado documental"><option value="">Todos los estados</option>${options([['rojo','Con bloqueos'],['gris','Por definir'],['ambar','Con pendientes'],['verde','Completa']])}</select><select id="work-sort" aria-label="Ordenar"><option value="name">Ordenar por nombre</option><option value="phase">Ordenar por fase</option></select></div><div id="works-table">${projectTable(data.projects)}</div>`);const filter=()=>{let q=$('#work-search').value.toLowerCase(),color=$('#work-filter').value,sort=$('#work-sort').value;$('#works-table').innerHTML=projectTable(data.projects.filter(p=>(p.name+' '+p.municipality+' '+p.code).toLowerCase().includes(q)&&(!color||p.health.color===color)).sort((a,b)=>String(a[sort]).localeCompare(String(b[sort]))))};$('#work-search').oninput=filter;$('#work-filter').onchange=filter;$('#work-sort').onchange=filter}
function renderPipeline(){shell(pageTitle('Pipeline de proyectos','La fase de obra y la habilitación documental se gestionan por separado.')+`<div class="board">${meta.phases.map((phase,i)=>`<section class="lane" data-phase="${i}"><h3>${i+1}. ${E(phase)} · ${data.projects.filter(p=>p.phase===i).length}</h3>${data.projects.filter(p=>p.phase===i).map(p=>`<article class="card" draggable="true" data-project="${p.id}"><h3><a href="#obra/${p.id}">${E(p.name)}</a></h3><p>${healthTag(p.health)} ${p.paused?tag('Paralizada','rojo'):''}</p><small>${E(p.details.manager||'Gestor sin asignar')}<br>${dt(p.details.start)}<br>${p.health.critical} pendientes críticos</small><p>${E(p.next_action?.title||'Definir siguiente paso')}</p><small>${dt(p.next_action?.due)}</small><select class="phase-select" data-id="${p.id}" aria-label="Cambiar fase de ${E(p.name)}">${options(meta.phases.map((v,j)=>[String(j),v]),String(i))}</select></article>`).join('')}</section>`).join('')}</div><div class="notice">Los cambios quedan en el historial. Un cambio de fase no elimina pendientes. Los bloqueos y datos insuficientes requieren una excepción expresa de administración.</div>`);document.querySelectorAll('.phase-select').forEach(el=>el.onchange=()=>movePhase(el.dataset.id,Number(el.value)));document.querySelectorAll('[draggable]').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.project));document.querySelectorAll('.lane').forEach(el=>{el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();movePhase(e.dataTransfer.getData('text/plain'),Number(el.dataset.phase))}})}
async function movePhase(id,phase,exception_reason){try{await api('/projects/'+id,'PATCH',{phase,exception_reason});await refresh();toast('Fase actualizada; los requisitos conservan su estado.')}catch(e){if(!me.admin)return toast(e.message);showModal('Revisar bloqueo de paso',`<div class="notice warning">${E(e.message)}</div>${textarea('reason','Motivo de la excepción y autorización competente')}`,async b=>{await api('/projects/'+id,'PATCH',{phase,exception_reason:b.reason});close();await refresh()},'Registrar excepción y mover')}}
function renderEntities(kind){let cfg={companies:['Empresas','Empresas colaboradoras y sus participaciones.','+ Incorporar empresa','new-company'],workers:['Trabajadores','Identificación mínima, empresa y asignaciones.','+ Incorporar trabajador','new-worker'],equipment:['Equipos','Maquinaria, equipos y obras de utilización.','+ Incorporar equipo','new-equipment']}[kind];shell(pageTitle(cfg[0],cfg[1],btn(cfg[2],cfg[3],'','primary'))+`<div class="toolbar"><input id="entity-search" placeholder="Buscar…" aria-label="Buscar ${E(cfg[0])}"></div><div class="cards" id="entity-cards">${entityCards(kind,data[kind])}</div>`);$('#entity-search').oninput=e=>$('#entity-cards').innerHTML=entityCards(kind,data[kind].filter(x=>x.name.toLowerCase().includes(e.target.value.toLowerCase())))}
function entityCards(kind,items){return items.map(x=>`<article class="card"><div class="eyebrow">${E(kind==='companies'?x.kind:kind==='workers'?'PERSONAL':'EQUIPO')}</div><h2>${E(x.name)}</h2><p>${E(kind==='companies'?'Documentación por ámbito y obra':nameC(x.company_id))}</p><small>${E(x.trade||x.kind||'')}</small><div class="card-actions">${kind==='companies'&&me.admin?btn('Archivo general','company-archive',x.id):''}${kind==='workers'&&me.admin?btn('Ficha y contacto','worker-detail',x.id):''}${kind==='workers'&&!x.project_ids?.length?'<span class="badge gris">Sin obra asignada</span>':''}${(x.project_ids||data.projects.map(p=>p.id)).map(pid=>`<a class="button" href="#obra/${pid}">${E(nameP(pid))} ↗</a>`).join('')}</div></article>`).join('')||'<div class="empty">Todavía no hay registros visibles.</div>'}
function docCards(ds){return ds.map(d=>{let v=d.versions[0];return `<article class="card"><div class="eyebrow">${E(meta.categories.find(c=>c.id===d.category)?.name||d.category)}</div><h2>${E(d.title)}</h2><p>${E(nameP(d.project_id))} · ${E(nameC(d.company_id))}</p>${v?docTag(v.effective_status):''} <small>${v?'Versión vigente '+v.number:''}</small><div class="card-actions">${v?`<a class="button" href="/api/versions/${v.id}/file" target="_blank" rel="noopener">Descargar</a>${['review','validate','approve'].some(a=>can(d.project_id,a,d.company_id,d.category))?btn('Revisar','review',v.id):''}${can(d.project_id,'manage',d.company_id,d.category)?btn('Solicitar firma','new-signature',v.id):''}${d.company_id&&!v.reuse&&v.effective_status==='validado'&&can(d.project_id,'validate',d.company_id,d.category)?btn('Publicar como general','publish-library',v.id):''}`:''}${can(d.project_id,'upload',d.company_id,d.category)?btn('Nueva versión','new-version',d.id):''}</div><details><summary>Versiones e historial (${d.versions.length})</summary>${d.versions.map((v,i)=>`<div class="version"><strong>v${v.number} ${i===0?'· Vigente':'· Histórica'}</strong> · ${docTag(v.effective_status)}<br>${dt(v.created_at)} · ${E(v.provenance)}<br>Vigencia: ${dt(v.expires)}<br>${v.reviews?.length?`<div class="review-history">${v.reviews.map(r=>`<p><strong>${E(label(r.action))}</strong> · ${E(r.reviewer)} · ${dt(r.created_at)}<br>${E(r.reason)}</p>`).join('')}</div>`:''}${v.reuse?`<div class="notice">Reutilizado desde biblioteca de empresa · versión original ${E(v.reuse.source_version_number)} · aplicado ${dt(v.reuse.applied_at)}. Firma y aprobación técnica independientes.<br>Hash de origen: ${E(v.reuse.source_hash)}</div>`:''}<a href="/api/versions/${v.id}/file">Descargar versión</a><code>SHA256 ${E(v.hash)}</code></div>`).join('')}</details></article>`}).join('')||'<div class="empty">No hay documentos en esta vista.</div>'}
function signatureCards(ss){return ss.map(s=>`<div class="card"><h3>${E(s.title)}</h3><p>${tag(label(s.status),s.status==='completada'?'verde':'ambar')} ${tag('Firma simulada','ambar')}</p><small>Caducidad del trámite: ${dt(s.expires)}</small><div class="card-actions">${s.status==='completada'?`<a class="button" href="/api/signatures/${s.id}/archive">Resultado de prueba</a><a class="button" href="/api/signatures/${s.id}/archive?evidence=true">Evidencias</a>`:`${btn('Recordar (prueba)','remind-signature',s.id)}${btn('Cancelar','cancel-signature',s.id)}`}</div></div>`).join('')||'<div class="empty">No hay solicitudes de firma.</div>'}
function renderDocs(){shell(pageTitle('Documentos y firmas','Versiones, revisiones y firmas con estados independientes.',btn('Biblioteca de empresa','choose-library')+' '+btn('+ Subir documento','upload','','primary'))+`<div class="toolbar"><input id="doc-search" placeholder="Buscar documento, obra o empresa…" aria-label="Buscar documentos"><select id="doc-cat" aria-label="Categoría"><option value="">Todas las categorías</option>${options(meta.categories)}</select><select id="doc-state" aria-label="Estado"><option value="">Todos los estados</option>${options(Object.entries(statusNames).filter(([s])=>['recibido','en_revision','validado','rechazado','caducado'].includes(s)))}</select><input id="doc-date" type="date" aria-label="Fecha de carga desde"></div><div class="cards" id="doc-cards">${docCards(data.documents)}</div><div class="section-head"><h2>Solicitudes de firma</h2></div><div class="cards">${signatureCards(data.signatures)}</div>`);const filter=()=>{let q=$('#doc-search').value.toLowerCase(),cat=$('#doc-cat').value,state=$('#doc-state').value,date=$('#doc-date').value;$('#doc-cards').innerHTML=docCards(data.documents.filter(d=>(d.title+' '+nameP(d.project_id)+' '+nameC(d.company_id)).toLowerCase().includes(q)&&(!cat||cat===d.category)&&(!state||d.versions[0]?.effective_status===state)&&(!date||d.versions[0]?.created_at>=date)))};['#doc-search','#doc-cat','#doc-state','#doc-date'].forEach(s=>$(s).oninput=filter)}
function renderTasks(filter=''){shell(pageTitle('Tareas y próximos pasos','Cada pendiente tiene una acción. Cerrar una tarea no valida un documento.',btn('+ Nueva tarea','new-task','','primary'))+`<div class="toolbar"><select id="task-filter" aria-label="Vista de tareas">${options([['','Todas las abiertas'],['hoy','Hoy'],['semana','Próximos siete días'],['vencidas','Vencidas'],['tercero','Esperando a terceros'],['responsable','Sin responsable'],['fecha','Sin fecha'],['todas','Incluir completadas']],filter)}</select></div><div id="task-list"></div><div class="notice">Prioridad visible: bloqueo → alta; sin bloqueo → normal. Los ajustes manuales requieren motivo. Las fechas y dependencias se conservan por tarea.</div>`);const draw=()=>{let f=$('#task-filter').value,now=today(),week=new Date(Date.now()+7*864e5).toLocaleDateString('sv-SE',{timeZone:'Europe/Madrid'});let ts=data.tasks.filter(t=>(f==='todas'||!['completada','cancelada'].includes(t.status))&&(!f||f==='todas'||f==='hoy'&&t.due===now||f==='semana'&&t.due>=now&&t.due<=week||f==='vencidas'&&t.due&&t.due<now||f==='tercero'&&t.status==='esperando_tercero'||f==='responsable'&&!t.owner||f==='fecha'&&!t.due));$('#task-list').innerHTML=`<div class="panel">${ts.map(t=>`<div class="task-row"><div class="priority ${E(t.priority)}"></div><div class="body"><p>${E(t.title)}</p><small>${E(nameP(t.project_id))} · Actúa: ${E(t.actor||'Sin asignar')} · Seguimiento: ${E(t.owner||'Sin asignar')} · ${dt(t.due)}</small><small>${E(t.origin)} · Prioridad ${E(t.priority)}</small></div>${docTag(t.status)}${btn('Gestionar','edit-task',t.id)}</div>`).join('')||'<div class="empty">No hay tareas en esta vista.</div>'}</div>`};$('#task-filter').onchange=draw;draw()}
function renderCalendar(){let events=[...data.tasks.filter(t=>t.due).map(t=>({date:t.due,title:t.title,type:'Tarea',pid:t.project_id})),...data.documents.filter(d=>d.versions[0]?.expires).map(d=>({date:d.versions[0].expires,title:d.title,type:'Vencimiento',pid:d.project_id})),...data.signatures.map(s=>({date:s.expires.slice(0,10),title:s.title,type:'Firma',pid:s.project_id})),...data.projects.flatMap(p=>['start','end'].filter(k=>p.details[k]).map(k=>({date:p.details[k],title:p.name,type:k==='start'?'Inicio previsto':'Final previsto',pid:p.id})))].sort((a,b)=>a.date.localeCompare(b.date));shell(pageTitle('Calendario e hitos','Fechas previstas, documentación y trámites. Sin plazos inventados.',btn('+ Añadir hito','new-milestone','','primary'))+`<div class="panel">${events.map(e=>`<div class="task-row"><div><strong>${dt(e.date)}</strong><small>${E(e.type)}</small></div><div class="body"><p>${E(e.title)}</p><small>${E(nameP(e.pid))}</small></div><a href="#obra/${e.pid}">Abrir →</a></div>`).join('')||'<div class="empty">No hay fechas definidas. Añade fechas o hitos a una obra.</div>'}</div><div class="notice">${data.tasks.filter(t=>!t.due).length} tareas sin fecha definida. Los hitos adicionales se consultan en el resumen de cada obra.</div>`)}
const tabs=[['resumen','Resumen y próximos pasos'],['datos','Datos y agentes'],['licencias','Licencias y permisos'],['proyecto','Proyecto y planos'],['prl','PRL y coordinación'],['empresas','Empresas y trabajadores'],['equipos','Equipos'],['documentos','Documentos y firmas'],['actas','Actas e incidencias'],['calidad','Calidad y certificados'],['final','Final de obra'],['historial','Historial']];
function renderProject(){let p=currentProject,d=p.details,ps=data.documents.filter(x=>x.project_id===p.id),html='';if(currentTab==='resumen'){html=`<div class="twocol"><section><div class="section-head"><h2>Qué falta y cómo avanzar</h2>${healthTag(p.health)}</div><div class="panel">${p.health.causes.slice(0,8).map(c=>`<div class="task-row"><div class="body"><p>${E(c)}</p><small>Resolver en PRL y coordinación con el responsable competente.</small></div></div>`).join('')||'<div class="empty">No hay causas documentales visibles.</div>'}</div><div class="section-head"><h2>Próximos pasos</h2>${btn('+ Tarea','new-task',p.id)}</div><div class="panel">${taskRows(data.tasks.filter(t=>t.project_id===p.id&&!['completada','cancelada'].includes(t.status)),6)}</div></section><section><div class="section-head"><h2>Ficha rápida</h2>${btn('Editar datos','edit-project',p.id)}</div><div class="card">${[['Fase',meta.phases[p.phase]],['Tipo',p.has_project===null?'Sin definir':p.has_project?'Con proyecto':'Sin proyecto'],['Gestor',d.manager||'Sin asignar'],['Encargado',d.foreman||'Sin asignar'],['Inicio previsto',dt(d.start)],['Final previsto',dt(d.end)]].map(([k,v])=>`<div class="detail"><small>${E(k)}</small><span>${E(v)}</span></div>`).join('')}</div><div class="section-head"><h2>Hitos</h2>${btn('+ Hito','new-milestone',p.id)}</div><div class="card">${p.milestones.map(m=>`<p>${E(m.title)} · ${dt(m.date)}</p>`).join('')||'<small>Sin hitos definidos.</small>'}</div><div class="card-actions">${btn(p.paused?'Reanudar obra':'Paralizar obra','pause-project',p.id)}${btn('Exportar expediente','export',p.id)}</div></section></div>`}else if(currentTab==='datos'){let fields={address:'Dirección',description:'Descripción',promoter:'Promotor',contractors:'Contratistas',nm_role:'Papel de NM2022',manager:'Gestor interno',foreman:'Encargado',css:'Coordinador de seguridad y salud',prevention:'Servicio de prevención',activities:'Actividades y fases',risks:'Riesgos y trabajos especiales',max_workers:'Máximo de trabajadores simultáneos',preventive_resource:'Recurso preventivo: necesidad y designación',contacts:'Contactos',start:'Inicio previsto',end:'Final previsto',actual_start:'Inicio real',actual_end:'Final real',notes:'Observaciones'};html=`<div class="section-head"><h2>Datos de obra</h2>${btn('Editar ficha','edit-project',p.id)}</div>${d.import_proposal?`<details><summary>Datos propuestos a partir de los documentos (pendientes de confirmar)</summary><pre>${E(JSON.stringify(d.import_proposal,null,2))}</pre></details>`:''}<div class="card details-grid">${Object.entries(fields).map(([key,name])=>`<div class="detail"><small>${E(name)}</small><span>${E(d[key]||'Pendiente de definir')}</span></div>`).join('')}</div><div class="section-head"><h2>Agentes y funciones</h2>${btn('+ Agente','new-agent',p.id)}</div><div class="cards">${p.agents.map(a=>`<div class="card"><h3>${E(a.name)}</h3><p>${E(a.function)}</p></div>`).join('')||'<div class="empty">No se han incorporado agentes.</div>'}</div><div class="section-head"><h2>Acceso individual</h2>${me.admin?btn('+ Invitar técnico o colaborador','invite',p.id):''}</div><div class="panel">${p.invitations.map(i=>`<div class="task-row"><div class="body"><p>${E(i.name)} · ${E(i.role)}</p><small>${E(i.email)} · ${i.used_at?'Aceptada':i.revoked?'Revocada':'Pendiente'} · ${dt(i.expires)}</small></div>${!i.used_at&&!i.revoked?btn('Revocar','revoke-invite',i.id):''}</div>`).join('')||'<div class="empty">Sin invitaciones visibles.</div>'}</div>`}else if(currentTab==='prl'){html=`<div class="section-head"><h2>Requisitos aplicables</h2>${btn('Evaluar nuevos requisitos','generate',p.id)}</div><div class="notice warning">Catálogo orientativo pendiente de contraste con fuentes oficiales vigentes. La aplicabilidad, el fundamento y el carácter bloqueante deben resolverlos las personas competentes. No hay caducidades automáticas.</div><div class="panel">${p.requirements.map(r=>`<div class="req-row"><div><h3>${E(r.name)}</h3><small>${E(nameC(r.company_id))}${r.worker_id?' · Trabajador asignado':''}${r.equipment_id?' · Equipo asignado':''} · Regla v${r.rule_version}</small><p>${docTag(r.effective_status)} ${r.applicability==='pendiente_revision'?tag('Resolver aplicabilidad','gris'):tag('Aplicable',r.blocking?'rojo':'verde')} ${r.blocking?tag('Bloqueante','rojo'):''}</p>${r.reason?`<small>Justificación: ${E(r.reason)}</small>`:''}</div><div class="req-actions">${btn('Fundamento','req-info',r.id)}${can(p.id,'validate',r.company_id,r.category)?btn('Resolver','resolve-req',r.id):''}${can(p.id,'upload',r.company_id,r.category)?btn('Aportar','upload-req',r.id):''}${r.company_id&&!r.worker_id&&!r.equipment_id?btn('Reutilizar','req-library',r.id):''}</div></div>`).join('')||'<div class="empty">Sin requisitos visibles. Completa datos y evalúa requisitos.</div>'}</div><div class="notice">El registro interno de incidencias no sustituye al libro de incidencias oficial ni a otros libros o trámites reglamentarios.</div>`}else if(currentTab==='empresas'){html=`<div class="section-head"><h2>Participaciones en esta obra</h2>${btn('+ Incorporar empresa','new-company',p.id)}</div><div class="cards">${p.participations.map(c=>`<div class="card"><h2>${E(c.name)}</h2><p>${E(c.kind)} · ${E(c.role)}</p><small>${E(c.activity||'Actividad sin definir')}</small><div class="card-actions">${me.admin?btn('Invitar responsable','invite-company',c.company_id):''}${can(p.id,'upload',c.company_id,'prl')?btn('+ Trabajador','new-worker',c.company_id):''}${btn('Biblioteca de empresa','open-library',JSON.stringify({pid:p.id,cid:c.company_id}))}</div></div>`).join('')}</div><div class="section-head"><h2>Trabajadores asignados</h2></div><div class="cards">${entityCards('workers',data.workers.filter(w=>w.project_ids.includes(p.id)))}</div>`}else if(currentTab==='equipos'){html=`<div class="section-head"><h2>Equipos asignados</h2>${btn('+ Equipo','new-equipment',p.id)}</div><div class="cards">${entityCards('equipment',data.equipment.filter(w=>w.project_ids.includes(p.id)))}</div>`}else if(currentTab==='historial'){html=`<div class="panel">${p.audit.map(a=>`<div class="task-row"><div class="body"><p>${E(a.action)}</p><small>${E(a.user_name||'Sistema')} · ${dt(a.created_at)}</small><details><summary>Detalles</summary><pre>${E(a.details)}</pre></details></div></div>`).join('')||'<div class="empty">Historial reservado a administración.</div>'}</div>`}else{let category=currentTab==='documentos'?null:currentTab;html=`<div class="section-head"><h2>${E(tabs.find(t=>t[0]===currentTab)?.[1])}</h2>${btn('+ Subir documento','upload',p.id)}</div><div class="cards">${docCards(ps.filter(d=>!category||d.category===category))}</div>${currentTab==='documentos'?`<div class="section-head"><h2>Firmas</h2></div><div class="cards">${signatureCards(data.signatures.filter(s=>s.project_id===p.id))}</div>`:''}${currentTab==='actas'?'<div class="notice">Registro interno: no sustituye el libro de incidencias oficial.</div>':''}`}
 shell(pageTitle(p.name,p.code+' · '+(p.municipality||'Municipio pendiente')+' · '+meta.phases[p.phase],btn('Plantillas PDF','templates',p.id)+' '+btn('Exportar','export',p.id))+`${d.import_pending_confirmation?'<div class="notice warning">Ficha creada a partir de documentos aportados. Revisa los datos y las diferencias entre fuentes antes de confirmarlos.</div>':''}<div class="tabs">${tabs.map(([id,text])=>btn(text,'tab',id,currentTab===id?'selected':'')).join('')}</div>${html}`)}
function renderSettings(){shell(pageTitle('Configuración','Plantillas versionadas, categorías, accesos y buzón de pruebas.')+`<div class="toolbar">${btn('+ Categoría','new-category')}${btn('+ Regla documental','new-rule')}${btn('Procesar alertas','run-alerts')}</div><div class="notice warning">Reglas iniciales sin verificación oficial. No se aplican como obligaciones legales confirmadas. La revisión requiere fuente y justificación. Las instantáneas de expedientes existentes no cambian.</div><div class="section-head"><h2>Reglas documentales (${settings.rules.length})</h2></div><div class="panel">${settings.rules.map(r=>`<div class="req-row"><div><h3>${E(r.name)}</h3><small>${E(r.scope)} · ${E(r.condition)} · ${E(r.classification)} · v${r.version}</small><small>${r.approved_by?'Revisada el '+dt(r.review_date):'Pendiente de revisión competente'}</small></div>${btn('Revisar plantilla','review-rule',r.id)}</div>`).join('')}</div><div class="section-head"><h2>Buzón de pruebas</h2><small>No envía comunicaciones reales</small></div><div class="panel">${settings.outbox.map(m=>`<div class="task-row"><div class="body"><p>${E(m.subject)}</p><small>${E(m.recipient)} · ${E(m.status)}</small></div></div>`).join('')||'<div class="empty">El buzón de pruebas está vacío.</div>'}</div><div class="section-head"><h2>Usuarios y ámbitos</h2></div><div class="cards">${settings.users.map(u=>`<div class="card"><h3>${E(u.name)}</h3><p>${E(u.email)}</p><small>${u.admin?'Administración':settings.grants.filter(g=>g.user_id===u.id).map(g=>g.role+' · '+nameP(g.project_id)).join(', ')}</small><div class="card-actions">${settings.grants.filter(g=>g.user_id===u.id).map(g=>btn('Revocar '+g.role+' · '+nameP(g.project_id),'revoke-grant',g.id)).join('')}</div></div>`).join('')}</div>`)}
function projectSelect(pid=''){return select('project_id','Obra',data.projects,pid||currentProject?.id||'')}
function companySelect(cid='',empty=true){let cs=currentProject?currentProject.participations.map(p=>({id:p.company_id,name:p.name})):data.companies;return select('company_id','Empresa / ámbito',[...(empty?[['','Ámbito general de la obra']]:[]),...cs],cid)}
function newProject(){showModal('Crear obra',`<div class="form-grid">${input('name','Nombre de obra','text','',true)}${input('code','Código','text','',true)}${input('municipality','Municipio')}${select('has_project','Tipo de obra',[['','Sin definir'],['1','Con proyecto'],['0','Sin proyecto']])}${textarea('description','Descripción')}</div><div class="notice">Puedes guardar una ficha incompleta. Los datos pendientes quedarán identificados.</div>`,async b=>{let p=await api('/projects','POST',{...b,has_project:b.has_project===''?null:b.has_project==='1',details:{description:b.description}});close();data=await api('/dashboard');currentTab='resumen';location.hash='obra/'+p.id})}
function editProject(){let p=currentProject,d=p.details;let fields={address:'Dirección',promoter:'Promotor',contractors:'Contratistas',nm_role:'Papel de NM2022',manager:'Gestor interno',foreman:'Encargado',css:'Coordinador de seguridad y salud',prevention:'Servicio de prevención',max_workers:'Máximo de trabajadores simultáneos',preventive_resource:'Recurso preventivo',contacts:'Contactos'};showModal('Completar ficha de obra',`<div class="form-grid">${input('project_name','Nombre de obra','text',p.name,true)}${input('project_code','Código','text',p.code,true)}${input('project_municipality','Municipio','text',p.municipality||'')}${p.has_project===null?select('project_type','Tipo de obra',[['','Sin definir'],['1','Con proyecto'],['0','Sin proyecto']]):''}${Object.entries(fields).map(([k,n])=>input(k,n,'text',d[k]||'')).join('')}${['start','end','actual_start','actual_end'].map((k,i)=>input(k,['Inicio previsto','Final previsto','Inicio real','Final real'][i],'date',d[k]||'')).join('')}${textarea('description','Descripción',d.description||'')}${textarea('activities','Fases y actividades',d.activities||'')}${textarea('risks','Riesgos y trabajos especiales',d.risks||'')}${textarea('notes','Observaciones',d.notes||'')}</div>`,async b=>{const payload={name:b.project_name,code:b.project_code,municipality:b.project_municipality};if(p.has_project===null)payload.has_project=b.project_type===''?null:b.project_type==='1';for(const k of ['project_name','project_code','project_municipality','project_type'])delete b[k];await api('/projects/'+p.id,'PATCH',{...payload,details:b});close();await refresh()})}
function newCompany(pid=''){showModal('Incorporar empresa a obra',`<div class="form-grid">${projectSelect(pid)}${select('company_id','Empresa existente o nueva',[['','Crear nueva empresa'],...data.companies])}${input('name','Nombre (solo empresa nueva)','text','')}${select('kind','Tipo de participante',[['con_trabajadores','Empresa con trabajadores'],['autonomo','Autónomo'],['suministro','Proveedor de materiales']])}${select('role','Participación',[['subcontrata','Subcontrata ejecutora'],['contratista','Contratista'],['instalador','Instalador'],['suministro','Solo suministro'],['otro','Otro']])}${textarea('activity','Actividad y alcance contratado')}</div>`,async b=>{await api('/companies','POST',b);close();await refresh();toast('Empresa incorporada. Se han generado candidatos documentales para evaluar.')})}
function newPerson(kind,cid=''){showModal(kind==='workers'?'Incorporar trabajador':'Incorporar equipo',`<div class="form-grid">${projectSelect()}${companySelect(data.companies.some(c=>c.id===cid)?cid:'',false)}${input('name',kind==='workers'?'Nombre mínimo necesario':'Identificación del equipo','text','',true)}${kind==='workers'?input('trade','Oficio / funciones'):select('kind','Tipo de equipo',[['herramienta','Herramienta'],['andamio','Andamio'],['plataforma','Plataforma elevadora'],['elevacion','Equipo de elevación'],['tierras','Movimiento de tierras'],['otro','Otro']])}</div><div class="notice">No cargues DNI completo, nóminas, diagnósticos o historias clínicas. Aporta únicamente datos necesarios.</div>`,async b=>{await api('/people/'+kind,'POST',b);close();await refresh()})}
function uploadDocument(did='',reqId=''){let d=data.documents.find(x=>x.id===did),r=currentProject?.requirements.find(x=>x.id===reqId);if(r&&!d)d=data.documents.find(x=>x.requirement_id===r.id);let pid=d?.project_id||currentProject?.id||'',cid=d?.company_id||r?.company_id||'',cat=d?.category||r?.category||(['licencias','proyecto','actas','calidad','final'].includes(currentTab)?currentTab:'prl');showModal(d?'Añadir nueva versión':'Subir documento',`<div class="form-grid">${projectSelect(pid)}${companySelect(cid)}${input('title','Título','text',d?.title||r?.name||'',true)}${select('category','Categoría',meta.categories,cat)}${input('expires','Vigencia hasta (solo si corresponde)','date')}${input('validity_reason','Fundamento de vigencia, si se indica')}${input('file','Archivo PDF, JPG o PNG','file','',true,'full')}${input('issuer','Organismo emisor')}${input('reference','N.º de expediente')}${textarea('conditions','Condiciones, horarios y ubicación (permisos temporales)')}<label class="full check"><input type="checkbox" name="external_signed"> Documento firmado externamente, pendiente de revisión</label>${input('external_source','Procedencia externa (correo, WhatsApp u otro)','text','',false,'full')}</div><div class="notice">El archivo se recibirá sin validar. Solo conclusiones de aptitud; nunca historias clínicas o resultados médicos. PDF e imágenes se procesan para retirar contenido activo y metadatos.</div>`,async(b,form)=>{let f=new FormData();let file=form.elements.file.files[0];f.append('file',file);f.append('metadata',JSON.stringify({project_id:b.project_id,company_id:b.company_id||null,category:b.category,title:b.title,document_id:d?.id,requirement_id:d?.requirement_id||r?.id||null,expires:b.expires||null,validity_reason:b.validity_reason,external_signed:!!b.external_signed,external_source:b.external_source,details:{issuer:b.issuer,reference:b.reference,conditions:b.conditions}}));await api('/documents','POST',f);close();await refresh();toast('Documento recibido. Pendiente de revisión.')},'Subir como recibido');$('#modal-form input[type=file]').accept='.pdf,.png,.jpg,.jpeg';if(d||r){$('#modal-form [name=project_id]').disabled=true;$('#modal-form [name=company_id]').disabled=true;$('#modal-form [name=category]').disabled=true;let form=$('#modal-form');form.addEventListener('submit',()=>{},false); // disabled fields are explicitly retained by hidden inputs
 for(let [name,val] of [['project_id',pid],['company_id',cid],['category',cat]]){let x=document.createElement('input');x.type='hidden';x.name=name;x.value=val;form.appendChild(x)}}}
function inviteCompany(cid=''){showModal('Invitar a una persona',`<div class="form-grid">${projectSelect()}${companySelect(cid)}${input('name','Nombre','text','',true)}${input('email','Correo electrónico','email','',true)}${select('role','Perfil',[['empresa','Empresa colaboradora'],['direccion','Dirección facultativa'],['encargado','Encargado'],['prl','Coordinación / técnico PRL'],['gestor','Gestor interno'],['firmante','Firmante']])}${select('category','Categorías autorizadas',[['seguras','Categorías generales (sin datos restringidos)'],...meta.categories.filter(c=>!c.sensitive)])}</div><details><summary>Permisos específicos (opcional)</summary><label class="check"><input type="checkbox" name="custom_permissions">Usar permisos seleccionados</label>${['read','upload','review','validate','approve','sign','download','export','manage'].map(p=>`<label class="check"><input type="checkbox" name="perm-${p}">${E({read:'Consulta',upload:'Carga',review:'Revisión',validate:'Validación',approve:'Aprobación',sign:'Firma',download:'Descarga',export:'Exportación',manage:'Gestión'}[p])}</label>`).join('')}</details><div class="notice">Solo administración puede conceder permisos. La invitación es de un solo uso y caduca en siete días. Cada enlace de firma exige después la cuenta del firmante.</div>`,async b=>{let out=await api('/invitations','POST',{...b,company_id:b.company_id||null,...(b.custom_permissions?{permissions:Object.keys(b).filter(k=>k.startsWith('perm-')).map(k=>k.slice(5))}:{}),categories:b.category==='seguras'?meta.categories.filter(c=>!c.sensitive).map(c=>c.id):[b.category]});close();await refresh();shareModal('Invitación al portal',out.link,b.project_id,'Accede a tus trámites y configura tu cuenta.',out.expires)})}
function shareModal(title,path,pid,ask,expires,sid){let link=new URL(path,location.origin).href,message=`Nou Mallorca / NM2022 S.L.\nObra: ${nameP(pid)}\n${title}\nPetición: ${ask}\nEnlace del trámite (caduca ${dt(expires)}): ${link}`;showModal('Compartir solicitud',`<p>${E(title)}</p><div class="linkbox">${E(link)}</div><pre>${E(message)}</pre><div class="sharing">${btn('Copiar enlace','copy',link)}${btn('Copiar mensaje','copy',message)}<a class="button" href="https://wa.me/?text=${encodeURIComponent(message)}" target="_blank" rel="noopener">WhatsApp ↗</a><a class="button" href="mailto:?subject=${encodeURIComponent(title+' · '+nameP(pid))}&body=${encodeURIComponent(message)}">Preparar correo ↗</a>${sid?btn('Confirmo que lo he enviado','confirm-sent',sid):''}</div><div class="notice">Abrir WhatsApp o correo no acredita envío ni entrega. El correo abre un borrador sin adjuntar archivos. Descarga el documento si necesitas adjuntarlo manualmente. El enlace solo autoriza el trámite indicado.</div>`)}
async function requestSignature(vid){let d=data.documents.find(d=>d.versions.some(v=>v.id===vid));let users=await api(`/projects/${d.project_id}/signer-options?category=${encodeURIComponent(d.category)}${d.company_id?'&company_id='+d.company_id:''}`);if(!users.length)return toast('Invita antes a un firmante con permisos sobre este documento.');showModal('Solicitar firma de prueba',`<p>${E(d.title)}</p><div class="notice warning">Adaptador de pruebas. Produce un justificante simulado y conserva el original; no crea una firma avanzada, cualificada ni una aprobación técnica.</div>${select('mode','Orden de firma',[['paralela','Paralela'],['secuencial','Secuencial (orden de selección)']])}<label>Firmantes (orden mostrado)</label>${users.map(u=>`<label class="check"><input type="checkbox" name="signer-${u.id}">${E(u.name)} · ${E(u.email)}</label>`).join('')}${input('function','Función de los firmantes','text','Firmante',true)}`,async(b,form)=>{let selected=users.filter(u=>form.elements['signer-'+u.id].checked);if(!selected.length)throw Error('Selecciona al menos un firmante.');let r=await api('/signatures','POST',{version_id:vid,mode:b.mode,signers:selected.map(u=>({user_id:u.id,function:b.function}))});close();await refresh();if(r.links.length===1)shareModal(d.title,r.links[0].link,d.project_id,'Consulta el documento y realiza la firma simulada.',r.expires,r.id);else showModal('Enlaces individuales de firma',`<div class="notice warning">PRUEBA. Comparte cada enlace únicamente con su firmante. Se exige iniciar sesión con su cuenta.</div>${r.links.map(l=>`<div class="card"><h3>${E(users.find(u=>u.id===l.user_id).name)}</h3><div class="linkbox">${E(new URL(l.link,location.origin).href)}</div>${btn('Compartir','share-individual',JSON.stringify({link:l.link,title:d.title,pid:d.project_id,expires:r.expires,sid:r.id}))}</div>`).join('')}`)},'Crear solicitud simulada')}
async function invitationPage(token){try{let i=await api('/invitations/'+token);app.innerHTML=`<main class="auth">${brandMarkup('auth-brand')}<div class="eyebrow">NOU MALLORCA · INVITACIÓN SEGURA</div><h1>Tu espacio de colaboración</h1><p>${E(i.name)} · ${E(i.email)}<br>${E(i.project_name)} · ${E(i.role)}</p><form id="accept-invite">${input('password','Contraseña nueva (mínimo 12 caracteres)','password','',!me)}<p class="error" id="invite-error"></p><button class="primary">Aceptar invitación</button></form><div class="notice">Si ya tienes cuenta, inicia sesión con ${E(i.email)} antes de aceptar.</div>${btn('Iniciar sesión','login-view')}</main>`;$('#accept-invite').onsubmit=async ev=>{ev.preventDefault();try{await api('/invitations/'+token+'/accept','POST',Object.fromEntries(new FormData(ev.target)));toast('Invitación aceptada. Ya puedes iniciar sesión.');location.hash='dashboard';if(me)await boot();else loginPage()}catch(e){$('#invite-error').textContent=e.message}}}catch(e){loginPage(e.message)}}
async function signaturePage(token){try{let s=await api('/sign/'+token);shell(pageTitle('Consultar y firmar',s.title)+`<div class="notice warning">FIRMA SIMULADA · Entorno de pruebas. No tiene validez de firma electrónica y no implica aprobación técnica.</div><div class="card"><h2>${E(s.title)} · v${s.version}</h2><p>Función: ${E(s.function)} · Caduca: ${dt(s.expires)}</p><small>SHA256: ${E(s.hash)}</small><p><a class="button" href="/api/versions/${s.version_id}/file" target="_blank" rel="noopener">Consultar / descargar documento completo</a></p><iframe class="doc" title="Documento completo para consulta" src="/api/versions/${s.version_id}/file?inline=true"></iframe>${s.status==='completada'?'<div class="notice">Tu firma simulada ya se ha registrado. El resultado aparece en Documentos y firmas cuando todos completen.</div>':s.waiting?'<div class="notice">Esperando la firma de la persona anterior.</div>':`<form id="sign-form"><label class="check"><input type="checkbox" name="consent" required>He consultado el documento completo y confirmo mi intención de firmar en modo de prueba.</label><button class="primary">Confirmar firma simulada</button> ${btn('Rechazar','reject-sign',token)}<p class="error" id="sign-error"></p></form>`}</div>`);if($('#sign-form'))$('#sign-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/sign/'+token,'POST',{consent:true});data=await api('/dashboard');await signaturePage(token);toast('Firma de prueba registrada. El documento conserva su estado de revisión.')}catch(e){$('#sign-error').textContent=e.message}}}catch(e){shell(pageTitle('Trámite no disponible',e.message)+`<div class="notice">El enlace exige la cuenta del firmante asignado. Puede estar caducado o revocado.</div>${btn('Cambiar de cuenta','logout')}`)}}
function reviewVersion(vid){let d=data.documents.find(d=>d.versions.some(v=>v.id===vid));showModal('Revisión documental',`<p>${E(d.title)}</p><p><a class="button" href="/api/versions/${vid}/file" target="_blank" rel="noopener">Consultar archivo</a></p>${select('action','Acción expresa',[['en_revision','Iniciar revisión'],['rechazado','Rechazar y solicitar corrección'],['validado','Validar documentación'],['aprobado','Aprobar técnicamente (acción separada)']])}${textarea('reason','Motivo, observaciones y acción necesaria')}<div class="notice">La aprobación requiere permisos adecuados y validación previa. La firma es independiente.</div>`,async b=>{await api('/versions/'+vid+'/review','POST',b);close();await refresh()},'Registrar revisión')}
function resolveRequirement(rid){let r=currentProject.requirements.find(r=>r.id===rid);showModal('Resolver aplicabilidad',`<p>${E(r.name)}</p>${select('action','Decisión',[['aplica','Aplicable a este caso'],['no_aplicable','No aplica, con justificación']])}<label class="check"><input name="blocking" type="checkbox" ${r.blocking?'checked':''}>Bloqueante si queda incumplido</label>${textarea('reason','Fundamento y justificación del responsable competente')}<div class="notice warning">Esta decisión afecta solo a este expediente. No convierte el catálogo inicial en una obligación legal verificada.</div>`,async b=>{await api('/requirements/'+rid,'POST',{...b,blocking:!!b.blocking});close();await refresh()})}
function newTask(pid=''){let deps=data.tasks.filter(t=>t.project_id===(pid||currentProject?.id));showModal('Nueva tarea',`<div class="form-grid">${projectSelect(pid)}${companySelect()}${input('title','Acción concreta','text','',true,'full')}${input('actor','Persona o empresa que debe actuar')}${input('owner','Responsable interno de seguimiento')}${input('due','Fecha límite','date')}${select('priority','Prioridad',[['normal','Normal'],['alta','Alta'],['urgente','Urgente']])}${select('dependency','Depende de',[['','Sin dependencia'],...deps.map(t=>[t.id,t.title])])}${textarea('priority_reason','Justificación de prioridad')}</div>`,async b=>{await api('/tasks','POST',{...b,company_id:b.company_id||null,dependencies:b.dependency?[b.dependency]:[]});close();await refresh()})}
async function editTask(tid){
 const t=data.tasks.find(t=>t.id===tid),history=await api('/tasks/'+tid+'/history');
 const editable=can(t.project_id,'manage',t.company_id);
 const comments=history.comments.map(c=>`<div class="version"><strong>${E(c.author)}</strong> · ${dt(c.created_at)}<p>${E(c.body)}</p></div>`).join('')||'<p class="muted">Sin comentarios.</p>';
 const deps=history.dependencies.map(d=>`<p>${E(d.title)} · ${E(label(d.status))}</p>`).join('')||'<p class="muted">Sin dependencias.</p>';
 const historyHtml=`<details><summary>Dependencias (${history.dependencies.length})</summary>${deps}</details><details><summary>Historial de actuaciones (${history.events.length})</summary>${history.events.map(e=>`<div class="version">${E(e.author||'Sistema')} · ${dt(e.created_at)} · ${E(e.action)}<pre>${E(e.details)}</pre></div>`).join('')||'<p>Sin actuaciones manuales.</p>'}</details><h3>Comentarios</h3>${comments}${btn('Añadir comentario','comment-task',tid)}`;
 const fields=editable?`<div class="form-grid">${select('status','Estado',[['pendiente','Pendiente'],['en_curso','En curso'],['esperando_tercero','Esperando a tercero'],['completada','Completada'],['cancelada','Cancelada']],t.status)}${input('due','Fecha límite','date',t.due||'')}${input('actor','Debe actuar','text',t.actor||'')}${input('owner','Seguimiento interno','text',t.owner||'')}${select('priority','Prioridad',[['normal','Normal'],['alta','Alta'],['urgente','Urgente']],t.priority)}${textarea('reason','Comentario / motivo del ajuste de prioridad')}</div>`:`<p>${E(label(t.status))} · ${dt(t.due)}</p>`;
 showModal(editable?'Gestionar actuación':'Consultar pendiente',`<p>${E(t.title)}</p>${fields}<div class="notice">Completar esta tarea no modifica ni valida los requisitos documentales.</div>${historyHtml}`,editable?async b=>{if(b.priority===t.priority)delete b.priority;await api('/tasks/'+tid,'PATCH',b);close();await refresh()}:null);
}
function commentTask(tid){close();showModal('Añadir comentario al pendiente',textarea('body','Comentario o acción realizada')+'<div class="notice">No incluyas diagnósticos, datos bancarios ni información innecesaria. El comentario será visible para los usuarios autorizados a consultar este pendiente.</div>',async b=>{await api('/tasks/'+tid+'/comments','POST',b);close();await editTask(tid)},'Registrar comentario')}
function exportModal(pid){showModal('Exportar expediente autorizado',`<p>Obra: ${E(nameP(pid))}</p><div class="notice">La exportación se filtra en el servidor por permisos de categoría, empresa, descarga y exportación. Incluye fecha de generación y filtros.</div><div class="sharing"><a class="button primary" href="/api/projects/${pid}/export?format=zip">Expediente ZIP</a><a class="button" href="/api/projects/${pid}/export?format=pdf">Pendientes PDF</a><a class="button" href="/api/projects/${pid}/export?format=csv">Tareas CSV</a></div><p class="muted">Los resultados y evidencias de firma simulada se identifican como PRUEBA.</p>`)}
async function action(name,id){switch(name){case 'worker-detail':return workerDetail(id);case 'authorize-chat':return authorizeChatImport();case 'revoke-import':await api('/imports/'+id+'/revoke','POST');close();return toast('Autorización temporal revocada.');case 'company-archive':return openCompanyArchive(id);case 'reload-app':return boot();case 'choose-library':return chooseLibrary();case 'open-library':{let x=JSON.parse(id);return openLibrary(x.pid,x.cid,x.rid)}case 'req-library':{let r=currentProject.requirements.find(r=>r.id===id);return openLibrary(currentProject.id,r.company_id,r.id)}case 'publish-library':return publishLibrary(id);case 'apply-library':{let x=JSON.parse(id);return applyLibrary(x)}case 'revoke-library':{let x=JSON.parse(id);return showModal('Revocar publicación general',textarea('reason','Motivo y acción necesaria'),async b=>{await api('/library/'+x.id+'/revoke','POST',b);close();await refresh();toast('Publicación revocada. El histórico se conserva y los estados se recalculan.')})}case 'templates':return showModal('Generar borrador de plantilla',`<div class="notice warning">Borradores orientativos sin aprobar. Requieren completar contenido y revisión competente antes de su uso.</div><div class="sharing">${[['solicitud','Solicitud documental'],['pss','Toma de datos PSS'],['recepcion','Recepción de información'],['acta','Acta de coordinación'],['epis','Entrega EPIs'],['designacion','Designaciones'],['autorizacion','Autorizaciones'],['adhesion','Conocimiento o adhesión']].map(([n,t])=>`<a class="button" href="/api/templates/${n}/draft?project_id=${id}">${E(t)}</a>`).join('')}</div>`);case 'close':return close();case 'logout':await api('/logout','POST');me=null;return loginPage();case 'login-view':return loginPage();case 'go':location.hash=id;return;case 'new-project':return newProject();case 'filter-blocked':location.hash='obras';setTimeout(()=>{if($('#work-filter')){$('#work-filter').value='rojo';$('#work-filter').dispatchEvent(new Event('change'))}},100);return;case 'new-company':return newCompany(id);case 'new-worker':return newPerson('workers',id);case 'new-equipment':return newPerson('equipment');case 'upload':return uploadDocument();case 'new-version':return uploadDocument(id);case 'upload-req':return uploadDocument('',id);case 'review':return reviewVersion(id);case 'tab':currentTab=id;return renderProject();case 'edit-project':return editProject();case 'invite':return inviteCompany();case 'invite-company':return inviteCompany(id);case 'revoke-invite':await api('/invitations/'+id+'/revoke','POST');await refresh();return toast('Invitación revocada.');case 'resolve-req':return resolveRequirement(id);case 'req-info':{let r=currentProject.requirements.find(r=>r.id===id),s=JSON.parse(r.snapshot);return showModal('Fundamento y regla conservada',`<h3>${E(r.name)}</h3><div class="notice">${s.approved_by?'Plantilla revisada':'Pendiente de definición y revisión competente'}</div><pre>${E(JSON.stringify(s,null,2))}</pre>`)}case 'generate':await api('/projects/'+id+'/generate','POST');await refresh();return toast('Requisitos evaluados sin duplicar los existentes.');case 'new-signature':return requestSignature(id);case 'share-individual':{let x=JSON.parse(id);close();return shareModal(x.title,x.link,x.pid,'Consulta el documento y realiza la firma simulada.',x.expires,x.sid)}case 'copy':try{await navigator.clipboard.writeText(id);toast('Copiado al portapapeles.')}catch{toast('El navegador requiere HTTPS para copiar. Selecciona el texto del enlace.')}return;case 'confirm-sent':await api('/signatures/'+id+'/confirm-sent','POST');return toast('Registrado como confirmación del usuario, sin entrega acreditada.');case 'cancel-signature':await api('/signatures/'+id+'/cancel','POST');return refresh();case 'remind-signature':await api('/signatures/'+id+'/remind','POST');return toast('Recordatorio guardado en el buzón de pruebas. No se ha enviado correo.');case 'reject-sign':return showModal('Rechazar firma',textarea('reason','Motivo del rechazo'),async b=>{await api('/sign/'+id,'POST',{action:'reject',reason:b.reason});close();await refresh()});case 'new-task':return newTask(id);case 'edit-task':return editTask(id);case 'comment-task':return commentTask(id);case 'export':return exportModal(id);case 'new-agent':return showModal('Añadir agente y función',input('name','Nombre','text','',true)+input('function','Función y competencias','text','',true),async b=>{await api('/agents','POST',{...b,project_id:currentProject.id});close();await refresh()});case 'new-milestone':return showModal('Añadir hito',projectSelect(id)+input('title','Hito','text','',true)+input('date','Fecha (opcional)','date'),async b=>{await api('/milestones','POST',b);close();await refresh()});case 'pause-project':if(currentProject.paused){await api('/projects/'+id,'PATCH',{paused:false});return refresh()}return showModal('Paralizar obra',textarea('pause_reason','Motivo de paralización'),async b=>{await api('/projects/'+id,'PATCH',{paused:true,...b});close();await refresh()});case 'new-category':return showModal('Nueva categoría',input('name','Nombre','text','',true),async b=>{await api('/categories','POST',b);meta=await api('/me');close();await refresh()});case 'new-rule':return showModal('Nueva regla documental',input('name','Nombre','text','',true)+select('scope','Ámbito',[['obra','Obra'],['empresa','Empresa'],['trabajador','Trabajador'],['equipo','Equipo']])+select('condition','Condición',[['siempre','Todas las entidades del ámbito'],['con_proyecto','Obra con proyecto'],['sin_proyecto','Obra sin proyecto'],['ejecuta','Empresa ejecutora con trabajadores'],['autonomo','Autónomo ejecutor'],['suministro','Solo suministro'],['montaje','Equipos que requieren evaluar montaje']])+select('category','Categoría',meta.categories)+select('classification','Clasificación',[['procedimiento_interno','Procedimiento interno'],['contractual','Contractual'],['legal','Legal (pendiente de verificar)'],['recomendacion_tecnica','Recomendación técnica']])+input('source','Fuente o fundamento'),async b=>{await api('/rules','POST',b);close();await refresh()});case 'review-rule':return showModal('Revisar plantilla documental',input('source','Fuente oficial o fundamento verificado','text','',true)+textarea('reason','Fundamento y justificación de la revisión')+'<label class="check"><input name="blocking" type="checkbox">Bloqueante cuando resulte aplicable</label><div class="notice">Actúa únicamente si eres competente para revisar esta regla. Los expedientes existentes mantienen su instantánea.</div>',async b=>{await api('/rules/'+id,'POST',{...b,blocking:!!b.blocking});close();await refresh()});case 'revoke-grant':await api('/grants/'+id,'DELETE');await refresh();return toast('Acceso revocado en el servidor.');case 'run-alerts':{let r=await api('/alerts/run','POST');return toast(r.created+' avisos nuevos. Sin correo real.')}}}
document.addEventListener('click',ev=>{let el=ev.target.closest('[data-action]');if(el){ev.preventDefault();Promise.resolve(action(el.dataset.action,el.dataset.id)).catch(e=>toast(e.message))}});
window.addEventListener('hashchange',()=>route().catch(e=>toast(e.message)));
boot();

function publishLibrary(vid){
 const d=data.documents.find(d=>d.versions.some(v=>v.id===vid));
 showModal('Publicar documento general de empresa',`<h3>${E(d.title)}</h3><p>${E(nameC(d.company_id))}</p><div class="notice warning">La publicación permite a usuarios autorizados de esta empresa reutilizar este archivo en sus otras obras. No publiques datos específicos de obra, trabajadores, equipos ni información restringida.</div><label class="check"><input type="checkbox" name="general_scope_confirmed" required>Confirmo que esta versión es documentación general de empresa y autorizo su uso en otras obras.</label>${textarea('reason','Fundamento y alcance de la reutilización')}`,async b=>{
  await api('/library','POST',{version_id:vid,reason:b.reason,general_scope_confirmed:!!b.general_scope_confirmed});close();toast('Versión publicada en la biblioteca de empresa.');
 },'Publicar versión concreta');
}
function chooseLibrary(){
 showModal('Seleccionar biblioteca de empresa',projectSelect()+companySelect('',false),async b=>{if(!b.company_id)throw Error('Selecciona una empresa participante.');close();await openLibrary(b.project_id,b.company_id)},'Abrir biblioteca');
}
async function openLibrary(pid,cid,rid=null){
 const [result,p]=await Promise.all([api('/library?project_id='+encodeURIComponent(pid)+'&company_id='+encodeURIComponent(cid)),api('/projects/'+pid)]);
 const req=rid?p.requirements.find(r=>r.id===rid):null;
 const items=result.items.filter(i=>!req||(i.category===req.category&&(!i.rule_id||i.rule_id===req.rule_id)));
 showModal('Biblioteca de '+nameC(cid),`<p>Destino: ${E(nameP(pid))}${req?' · '+E(req.name):''}</p><div class="notice">Cada aplicación conserva la versión, hash y origen. Se recibe pendiente de revisión en esta obra, sin heredar firmas o aprobación. Los cambios de versión no se aplican silenciosamente.</div>${items.map(i=>`<div class="card"><h3>${E(i.title)}</h3><p>${docTag(i.effective_status)} · versión ${i.source_version}</p><small>Vigencia: ${dt(i.expires)}<br>SHA256: ${E(i.hash)}</small><div class="card-actions">${i.effective_status!=='revocado'&&can(pid,'download',cid,i.category)?`<a class="button" href="/api/library/${i.id}/file?project_id=${pid}">Consultar versión</a>`:''}${i.available&&can(pid,'upload',cid,i.category)&&can(pid,'download',cid,i.category)?btn('Aplicar a esta obra','apply-library',JSON.stringify({id:i.id,pid,cid,rid,title:i.title,category:i.category,rule_id:i.rule_id})):''}${me.admin&&i.effective_status!=='revocado'?btn('Revocar publicación','revoke-library',JSON.stringify({id:i.id})):''}</div></div>`).join('')||'<div class="empty">No hay documentos generales publicados para este ámbito. Un revisor autorizado puede publicar una versión vigente y validada desde Documentos y firmas.</div>'}`);
}
async function applyLibrary(item){
 const p=await api('/projects/'+item.pid);
 const reqs=p.requirements.filter(r=>r.company_id===item.cid&&!r.worker_id&&!r.equipment_id&&r.category===item.category&&(!item.rule_id||r.rule_id===item.rule_id));
 close();showModal('Aplicar documento de empresa',`<h3>${E(item.title)}</h3><p>${E(nameP(item.pid))}</p>${item.rid?'<p>Requisito seleccionado desde el expediente.</p>':select('requirement_id','Requisito al que se aplica',[['','Archivar sin vincular a un requisito'],...reqs.map(r=>[r.id,r.name])])}${textarea('reason','Justificación de aplicación a esta obra')}<div class="notice">Se crea una aplicación trazable y pendiente de revisión. El archivo de origen y sus firmas no se modifican.</div>`,async b=>{
  await api('/library/'+item.id+'/apply','POST',{project_id:item.pid,requirement_id:item.rid||b.requirement_id||null,reason:b.reason});close();await refresh();toast('Documento reutilizado. Pendiente de revisión en esta obra.');
 },'Aplicar y conservar trazabilidad');
}

function renderChatImport(){
 if(!me.admin)return shell(pageTitle('Acceso restringido','La importación desde chat requiere administración.'));
 shell(pageTitle('Importar desde esta conversación','Incorpora adjuntos y trabajadores mediante una autorización temporal.')+`<div class="card"><h2>Autorizar una importación privada</h2><p>Los archivos ya compartidos en el chat pueden incorporarse directamente a la aplicación. Tú eliges el destino y el límite del lote.</p><div class="notice">El código dura una hora, se puede revocar y solo permite incorporar documentos y trabajadores. No permite leer el expediente, descargar archivos, validar documentos ni cambiar permisos.</div>${btn('Autorizar este lote','authorize-chat','','primary')}<p class="muted">La documentación queda recibida y pendiente de revisión. Los originales PDF se conservan sin alterar; no se verifican automáticamente sus firmas. Los trabajadores se registran sin asignarlos a obras ni crear cuentas de acceso.</p></div>`);
}
function authorizeChatImport(){
 if(!me.admin)return toast('Acción reservada a administración.');
 showModal('Autorizar importación desde el chat',projectSelectForImport()+select('company_id','Empresa de destino',[['','Identificar o crear a partir de los datos aportados'],...data.companies])+`<div class="form-grid">${input('max_files','Máximo de PDF','number','18',true)}${input('max_workers','Máximo de trabajadores','number','10',true)}</div><label class="check"><input type="checkbox" name="confirm" required>Autorizo este lote y la creación de la ficha de obra o empresa si he seleccionado esa opción.</label><div class="notice warning">Se permite el archivo general de empresa, incluido el laboral restringido a administración. No se importan permisos de otras aplicaciones, DNI completos, diagnósticos ni geolocalización del listado de trabajadores.</div>`,async b=>{
  const r=await api('/imports/authorize','POST',{project_id:b.project_id||null,company_id:b.company_id||null,max_files:Number(b.max_files),max_workers:Number(b.max_workers)});
  close();showModal('Código temporal de importación',`<p>Copia este código y pégalo en la misma conversación de ChatGPT donde has adjuntado los archivos.</p><div class="linkbox">${E(r.code)}</div><div class="sharing">${btn('Copiar código','copy',r.code)}${btn('Revocar código','revoke-import',r.id)}</div><p class="muted">Caduca en una hora. Límite: ${r.max_files} PDF y ${r.max_workers} trabajadores. No es tu contraseña de acceso.</p>`);
 },'Generar código temporal');
}
function projectSelectForImport(){return select('project_id','Destino de los documentos de obra',[['','Crear una obra a partir de los documentos aportados'],...data.projects])}
async function openCompanyArchive(cid){
 const r=await api('/company-archive/'+cid);
 showModal('Archivo general · '+nameC(cid),`<div class="notice">Documentación general de empresa, sin vinculación automática a ninguna obra. Acceso reservado a administración.</div>${r.documents.map(d=>`<div class="card"><h3>${E(d.title)}</h3><p>${E(meta.categories.find(c=>c.id===d.category)?.name||d.category)} · ${docTag(d.versions[0]?.status||'recibido')}</p>${d.versions.map(v=>`<p><a class="button" href="/api/company-archive/versions/${v.id}/file">Descargar v${v.number}</a></p><small>${dt(v.created_at)} · ${E(v.provenance)}</small>`).join('')}</div>`).join('')||'<p class="empty">Todavía no hay documentos generales en este archivo.</p>'}`);
}

function workerDetail(wid){
 const w=data.workers.find(x=>x.id===wid);if(!w||!me.admin)return;
 let d={};try{d=JSON.parse(w.details||'{}')}catch{}
 showModal('Ficha de trabajador',`<h3>${E(w.name)}</h3><p>${E(nameC(w.company_id))}</p><div class="detail"><small>Oficio</small>${E(w.trade||'Sin definir')}</div><div class="detail"><small>Correo de contacto</small>${E(d.email||'Sin definir')}</div><div class="detail"><small>Teléfono</small>${E(d.phone||'Sin definir')}</div><div class="detail"><small>Estado en el listado</small>${d.active===false?'Inactivo':d.active===true?'Activo':'Sin definir'}</div><div class="detail"><small>Obras asignadas</small>${w.project_ids?.length?w.project_ids.map(nameP).map(E).join(', '):'Sin asignación'}</div><div class="notice">El alta en el listado no implica formación validada, aptitud acreditada, firma ni habilitación documental para una obra.</div>`);
}
